// ELF backend v1 (ADR 0004, phase 5a/5b) — see elf_backend.hpp.
//
// The scheduling (frames, scope handling, loop labels, pending-alignment
// arithmetic, call plans) mirrors the P3 asm backend so behaviour stays in
// lockstep; the difference is that each instruction goes through the encoder
// into a byte buffer and labels are ids patched to rel32. Text parking and
// the refcount dance follow the same sequences the asm backend emits against
// hxrt; here they call the same ABI inside the freestanding runtime blob.
//
// Generated by tools/elfrtgen at build time: the freestanding runtime image
// (runtime/elfrt/enc_rt.c) plus the offsets of its public symbols inside it.
#include "encrt_blob.cpp"

#include "elf_backend.hpp"
#include "encoder.hpp"
#include "elf_writer.hpp"

#include "../ast.hpp"
#include "../backend.hpp"
#include "../ir.hpp"
#include "../type_resolver.hpp"

#include <algorithm>
#include <functional>
#include <map>
#include <memory>
#include <string>
#include <vector>

namespace backend {
namespace {

// SysV word argument registers, in order (v1: at most 6 word arguments).
const int CALL_REGS[6] = {RDI, RSI, RDX, RCX, R8, R9};

// xmm register numbering matches the Reg numbering (0..15); the SSE forms
// take raw numbers so keeping them as named constants documents intent.
constexpr int XMM0 = 0;
constexpr int XMM1 = 1;

bool is_word(TypeKind k) {
    return k == TypeKind::Int || k == TypeKind::Bool || k == TypeKind::Char;
}

bool is_v1_value(TypeKind k) {
    return is_word(k) || k == TypeKind::Decimal || k == TypeKind::Text;
}

// The register kind an expression evaluation leaves behind.
enum class Vm { Word, Dec, Txt };

struct LoopTargets {
    int brk = -1;
    int cont = -1;
};

// One emission context = one function frame.
struct Ctx {
    int label_id = -1;                     // position of the function body
    int ret_label = -1;                    // position of the epilogue reload
    std::map<std::string, int> locals;     // name -> rbp offset of its slot
    int slots = 0;                         // allocated 8-byte slots
    int frame = 0;                         // final rsp sub, 16-aligned
    int pending = 0;                       // outstanding 8-byte pushes
    std::vector<int> text_release;         // owned sd_str* slots, freed at exit
    int text_home[3] = {0, 0, 0};          // parked pointers around s[i]/calls
    int dec_scratch = 0;                   // one per frame, for decimal binops
    std::vector<LoopTargets> loops;
    int ret_slot = 0;                      // parked return value (all contexts)
    TypeKind ret_kind = TypeKind::Unknown;
    bool is_main_body = false;
};

class ElfBackend {
public:
    ElfBackend(Program& program, const std::string& source)
        : program_(program), source_file_(source) {}

    ~ElfBackend() {
        for (auto& [fn, c] : fn_ctx_) delete c;
    }

    std::vector<uint8_t> run() {
        // Placeholder builds (hosts without a System V x86-64 ELF toolchain
        // — see the HMX_ELF_BACKEND gate in CMakeLists.txt) carry an image
        // with no bindable runtime symbols; fail before emitting anything
        // so the user gets this message instead of a broken executable.
        if (encrt_syms_count == 0)
            err(0, "elf backend unavailable: this hmx binary was built without "
                   "the freestanding ELF runtime image (needs a System V x86-64 "
                   "Linux host with GNU binutils); build with -b c instead");

        TypeResolver resolver;
        resolver.resolve(program_);

        auto program_ir = ir::build(program_.statements);

        // User functions; lambdas/generic templates/nested fns reject at
        // their declaration with the source line.
        for (auto& top : program_ir) {
            if (top->kind != ir::SKind::FuncDecl) continue;
            auto* fn = static_cast<FunctionDecl*>(top->ast);
            if (!fn->type_params.empty())
                err(fn->line, "elf backend v1: generics are not supported (build with -b c)");
            if (fn->is_lambda || !fn->captures.empty())
                err(fn->line, "elf backend v1: closures/lambdas are not supported (build with -b c)");
            fns_.push_back(fn);
            fns_by_name_[fn->name] = fn;
            if (fn->name == "main") main_fn_ = fn;
        }
        if (main_fn_) {
            if (!main_fn_->params.empty())
                err(main_fn_->line, "elf backend v1: main cannot take parameters");
            if (main_fn_->has_return_type && !is_word(main_fn_->return_type))
                err(main_fn_->line, "elf backend v1: main must return int or nothing");
        }

        // Encoder labels for the runtime-image symbols are reserved up front
        // so call sites can reference them during generation.
        for (const char* sym : RT_SYMS)
            rt_ids_[sym] = E_.new_label();

        // ── layout pass: every context pre-allocates its slots so frames are
        //    known before the first emitted instruction of the body.
        ctx_main_.label_id = E_.new_label();
        ctx_main_.ret_label = E_.new_label();
        ctx_main_.is_main_body = true;
        scan_list(ctx_main_, program_ir, /*skip_fns=*/true);
        if (main_fn_) {
            auto main_ir = ir::build(main_fn_->body);
            scan_list(ctx_main_, main_ir, false);
        }
        finish_frame(ctx_main_);
        for (auto* fn : fns_) {
            if (fn == main_fn_) continue;
            check_fn_signature(fn);
            auto* c = new Ctx{};
            c->label_id = E_.new_label();
            c->ret_label = E_.new_label();
            c->ret_kind = fn->has_return_type ? fn->return_type : TypeKind::Unknown;
            for (auto& p : fn->params) declare_slot(*c, p.name, fn->line);
            fn_ctx_[fn] = c;
            auto body_ir = ir::build(fn->body);
            scan_list(*c, body_ir, false);
            finish_frame(*c);
        }

        // ── emit ──
        emit_entry_stub();
        bind(ctx_main_.label_id);
        emit_frame_head(ctx_main_);
        for (auto& top : program_ir) {
            if (top->kind != ir::SKind::FuncDecl) emit_node(ctx_main_, *top);
        }
        if (main_fn_) {
            auto body_ir = ir::build(main_fn_->body);
            for (auto& n : body_ir) emit_node(ctx_main_, *n);
        }
        emit_frame_tail(ctx_main_);

        for (auto* fn : fns_) {
            if (fn == main_fn_) continue;
            emit_function(fn);
        }

        // ── append the literal pool, then the freestanding runtime image ──
        size_t gen_len = code_.size();
        size_t pool_len = pool_.size();
        code_.resize(gen_len + pool_len + (size_t)encrt_image_len, 0);
        std::copy(pool_.begin(), pool_.end(),
                  code_.begin() + static_cast<long>(gen_len));
        std::copy(encrt_image, encrt_image + encrt_image_len,
                  code_.begin() + static_cast<long>(gen_len + pool_len));
        for (const auto& [lbl, off] : pool_offsets_)
            bind_at(lbl, gen_len + off);
        for (unsigned long i = 0; i < encrt_syms_count; i++)
            bind_at(rt_ids_[encrt_syms[i].name],
                    gen_len + pool_len + (size_t)encrt_syms[i].off);

        std::string enc_err;
        if (!E_.finish(&enc_err)) err(0, enc_err);

        // ── ELF wrap: single flat RX segment, entry at the stub ──
        ElfWriter w;
        return w.build(code_, /*entry_offset=*/0);
    }

private:
    Program& program_;
    std::string source_file_;

    std::vector<uint8_t> code_;
    std::vector<uint8_t> pool_;              // literal bytes (projected rodata)
    std::map<int, size_t> pool_offsets_;     // encoder label -> pool offset
    std::map<std::string, int> pool_ids_;    // dedup key -> encoder label

    Encoder E_{code_};

    std::vector<FunctionDecl*> fns_;
    std::map<std::string, FunctionDecl*> fns_by_name_;
    FunctionDecl* main_fn_ = nullptr;

    Ctx ctx_main_;
    std::map<FunctionDecl*, Ctx*> fn_ctx_;
    std::map<const void*, std::pair<int, int>> loop_slots_;  // LoopStmt* -> (count, i)
    std::map<const void*, int> call_text_slots_;             // CallExpr* -> region base

    Ctx* ctx_ = nullptr;   // current context during emit/scan helpers
    std::map<const void*, int> decl_slots_;   // VarDecl* -> frame offset
    std::map<std::string, int> rt_ids_;       // runtime symbol -> encoder label

    // Runtime symbols the v1 codegen may target; all must exist in the blob.
    static constexpr const char* RT_SYMS[] = {
        "_hmx_w_i64", "_hmx_w_char", "_hmx_w_f64", "_hmx_w_text",
        "_hmx_panic_chr", "sd_make_str", "sd_retain_str", "sd_release_str",
        "sd_concat", "sd_str_equals", "sd_str_cmp", "sd_str_view",
        "sd_check_index",
    };

    // ── diagnostics ─────────────────────────────────────────────────────────
    [[noreturn]] void err(int line, const std::string& msg) const {
        throw CompileError(line, msg);
    }

    // ── encoder labels ──────────────────────────────────────────────────────
    int new_label() { return E_.new_label(); }
    void bind(int id) { E_.bind(id); }
    void bind_at(int id, size_t at) { E_.bind_at(id, at); }

    // ── literal pool ────────────────────────────────────────────────────────
    // Appends raw bytes to the pool section (emitted between the code and the
    // runtime image) and returns an encoder label for RIP-relative access.
    // Every reference is position-relative inside the image, so the verbatim
    // relocation keeps them valid.
    int pooled_bytes(const std::string& key, const void* bytes, size_t n) {
        auto it = pool_ids_.find(key);
        if (it != pool_ids_.end()) return it->second;
        int lbl = new_label();
        size_t off = pool_.size();
        const uint8_t* b = static_cast<const uint8_t*>(bytes);
        pool_.insert(pool_.end(), b, b + n);
        pool_offsets_[lbl] = off;
        pool_ids_[key] = lbl;
        return lbl;
    }
    // Strings are stored NUL-terminated; doubles as their exact 8 bytes.
    int pool_str(const std::string& s) {
        return pooled_bytes("s" + s, s.data(), s.size() + 1);
    }
    int pool_double(double v) {
        std::string key("d");
        key.append(reinterpret_cast<const char*>(&v), sizeof(v));
        return pooled_bytes(key, &v, sizeof(v));
    }

    // ── frame layout ─────────────────────────────────────────────────────────
    void declare_slot(Ctx& c, const std::string& name, int line) {
        if (c.locals.count(name))
            err(line, "elf backend v1: duplicate declaration '" + name + "' in one function (shadowing is not supported)");
        c.slots++;
        c.locals[name] = -8 * c.slots;
    }

    bool decl_is_text(const VarDecl* v) {
        if (v->annotation == TypeKind::Text) return true;
        return v->annotation == TypeKind::Unknown && v->initializer &&
               v->initializer->resolved_type == TypeKind::Text;
    }

    // scan_list: pre-allocate slots for every local of a statement list.
    // Unknown kinds are ignored here (the emit pass reports them with a line
    // number); this keeps the scan pass throw-free except for slot rules.
    void scan_list(Ctx& c, const std::vector<std::unique_ptr<ir::Node>>& list, bool skip_fns) {
        for (auto& n : list) scan_node(c, *n, skip_fns);
    }

    void scan_node(Ctx& c, const ir::Node& n, bool skip_fns) {
        ctx_ = &c;
        switch (n.kind) {
            case ir::SKind::FuncDecl:
                if (!skip_fns)
                    err(n.ast->line, "elf backend v1: nested functions are not supported");
                return;
            case ir::SKind::VarDecl: {
                auto* v = static_cast<VarDecl*>(n.ast);
                TypeKind vt = v->annotation == TypeKind::Unknown
                                  ? (v->initializer ? v->initializer->resolved_type : TypeKind::Int)
                                  : v->annotation;
                if (!is_v1_value(vt) || !v->tuple_members.empty())
                    err(v->line, "elf backend v1: variable type of '" + v->name + "' is unsupported (int/bool/char/decimal/text)");
                if (v->initializer) scan_expr(c, v->initializer.get());
                // every declaration gets its own frame slot; the name is
                // bound by scope (restore logic lives in scan_scope)
                if (c.locals.count(v->name))
                    err(v->line, "elf backend v1: duplicate declaration '" + v->name + "' in one scope");
                c.slots++;
                decl_slots_[v] = -8 * c.slots;
                c.locals[v->name] = -8 * c.slots;
                if (decl_is_text(v)) c.text_release.push_back(c.locals[v->name]);
                return;
            }
            case ir::SKind::Assign: {
                auto* s = static_cast<AssignStmt*>(n.ast);
                if (s->rhs) scan_expr(c, s->rhs.get());
                return;
            }
            case ir::SKind::ExprStmt: {
                auto* s = static_cast<ExprStmt*>(n.ast);
                scan_expr(c, s->expr.get());
                return;
            }
            case ir::SKind::Print: {
                auto* s = static_cast<PrintStmt*>(n.ast);
                for (auto& e : s->args) scan_expr(c, e.get());
                return;
            }
            case ir::SKind::Return: {
                auto* s = static_cast<ReturnStmt*>(n.ast);
                for (auto& v : s->values) scan_expr(c, v.get());
                return;
            }
            case ir::SKind::If: {
                auto* s = static_cast<IfStmt*>(n.ast);
                scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                if (s->has_else) scan_scope(c, [&] {
                    for (auto& b : n.else_body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            case ir::SKind::While: {
                auto* s = static_cast<WhileStmt*>(n.ast);
                scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            case ir::SKind::DoWhile: {
                auto* s = static_cast<DoWhileStmt*>(n.ast);
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                scan_expr(c, s->condition.get());
                return;
            }
            case ir::SKind::For: {
                // the header declaration is scoped to header + body
                auto* s = static_cast<ForStmt*>(n.ast);
                std::string hdr;
                bool had = false;
                int prev = 0;
                if (n.init && n.init->kind == ir::SKind::VarDecl) {
                    hdr = static_cast<VarDecl*>(n.init->ast)->name;
                    auto it = c.locals.find(hdr);
                    if (it != c.locals.end()) { had = true; prev = it->second; }
                }
                if (n.init) scan_node(c, *n.init, skip_fns);
                if (s->condition) scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                if (n.update) scan_node(c, *n.update, skip_fns);
                if (had) c.locals[hdr] = prev;
                else if (!hdr.empty()) c.locals.erase(hdr);
                return;
            }
            case ir::SKind::Loop: {
                auto* l = static_cast<LoopStmt*>(n.ast);
                scan_expr(c, l->count.get());
                c.slots++;
                int cnt = -8 * c.slots;
                c.slots++;
                int ctr = -8 * c.slots;
                loop_slots_[l] = {cnt, ctr};
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            default:
                return;
        }
    }

    // Runs the scan of a nested block scope, then unbinds every name the
    // block declared (HMX block scoping: sibling blocks may redeclare).
    template <typename F>
    void scan_scope(Ctx& c, F&& f) {
        std::map<std::string, int> before(c.locals);
        f();
        for (auto it = c.locals.begin(); it != c.locals.end();) {
            if (before.count(it->first) == 0) it = c.locals.erase(it);
            else ++it;
        }
    }

    // Pre-scan of expressions: slots are needed for per-call-site parking of
    // text arguments (nested calls each get their own region, so composition
    // stays safe). Unknown expression shapes are ignored — the emit pass
    // reports them with a line number.
    void scan_expr(Ctx& c, Expression* e) {
        if (!e) return;
        if (auto* bin = dynamic_cast<BinaryExpr*>(e)) {
            scan_expr(c, bin->left.get());
            scan_expr(c, bin->right.get());
            return;
        }
        if (auto* n = dynamic_cast<NotExpr*>(e)) { scan_expr(c, n->operand.get()); return; }
        if (auto* n = dynamic_cast<NegExpr*>(e)) { scan_expr(c, n->operand.get()); return; }
        if (auto* cond = dynamic_cast<ConditionalExpr*>(e)) {
            scan_expr(c, cond->condition.get());
            scan_expr(c, cond->then_expr.get());
            scan_expr(c, cond->else_expr.get());
            return;
        }
        if (auto* cst = dynamic_cast<CastExpr*>(e)) { scan_expr(c, cst->operand.get()); return; }
        if (auto* idx = dynamic_cast<ArrayIndexExpr*>(e)) scan_expr(c, idx->index.get());
        if (auto* call = dynamic_cast<CallExpr*>(e)) {
            int n_text = 0;
            for (auto& a : call->args) {
                scan_expr(c, a.get());
                if (a->resolved_type == TypeKind::Text) n_text++;
            }
            if (n_text > 0) {
                // contiguous region: slot j (forward ordinal) at base - 8*j,
                // starting at the next free slot
                int base = -8 * (c.slots + 1);
                call_text_slots_[call] = base;
                c.slots += n_text;
            }
            return;
        }
    }

    void finish_frame(Ctx& c) {
        for (int i = 0; i < 3; i++) { c.slots++; c.text_home[i] = -8 * c.slots; }
        c.slots++;
        c.dec_scratch = -8 * c.slots;
        // Every context parks its return value in a dedicated slot: the
        // epilogue's text releases clobber rax/xmm0, so the value is reloaded
        // after them (main uses it for the process exit code, decimal
        // returns ride xmm0).
        c.slots++;
        c.ret_slot = -8 * c.slots;
        int bytes = (c.slots * 8 + 15) & ~15;   // 16-align
        c.slots = bytes / 8;
        c.frame = bytes;
    }

    void emit_frame_head(Ctx& c) {
        E_.push_r(RBP);
        E_.mov_r_r(RBP, RSP);
        E_.alu_ri(ALU_SUB, RSP, c.frame);
        // zero the ret slot: a bare `return` (or a loop-body re-entry) must
        // still produce a defined exit value for the frame tail reload.
        E_.mov_r_imm(RAX, 0);
        E_.mov_mem_r(RBP, c.ret_slot, RAX);
        // text slots are zeroed so a re-executed declaration can release the
        // old value safely (a NULL release is a no-op in the runtime)
        for (int off : c.text_release) {
            E_.mov_r_imm(RAX, 0);
            E_.mov_mem_r(RBP, off, RAX);
        }
    }

    void emit_frame_tail(Ctx& c) {
        bind(c.ret_label);
        // release owned text slots before the return reload
        for (int off : c.text_release) {
            E_.mov_r_mem(RDI, RBP, off);
            E_.call(rt_label("sd_release_str", 0));
        }
        // reload the parked return value after the releases; main reloads the
        // process exit code, decimal returns ride xmm0.
        if (c.ret_kind == TypeKind::Decimal)
            E_.movsd_xmm_mem(XMM0, RBP, c.ret_slot);
        else
            E_.mov_r_mem(RAX, RBP, c.ret_slot);
        E_.leave();
        E_.ret();
    }

    // ── entry stub: call main context, exit_group(result) ──
    void emit_entry_stub() {
        E_.alu_rr(ALU_XOR, RBP, RBP);   // rbp = 0 defensively
        E_.call(ctx_main_.label_id);
        E_.mov_r_r(RDI, RAX);
        E_.mov_eax_imm(231);            // SYS_exit_group
        E_.syscall();
    }

    // ── runtime helper calls ─────────────────────────────────────────────────
    int rt_label(const std::string& name, int line) {
        auto it = rt_ids_.find(name);
        if (it == rt_ids_.end())
            err(line, "elf backend v1: runtime symbol '" + name + "' is not in the runtime image");
        return it->second;
    }

    // Calls realign to 16 when mid-expression pushes are outstanding.
    void emit_call(int target) {
        if (ctx_->pending % 2 != 0) E_.alu_ri(ALU_SUB, RSP, 8);
        E_.call(target);
        if (ctx_->pending % 2 != 0) E_.alu_ri(ALU_ADD, RSP, 8);
    }

    // Byte write of a constant via the 1-byte runtime helper (separators).
    void emit_wchr_imm(int c) {
        E_.mov_edi_imm(c);
        emit_call(rt_label("_hmx_w_char", 0));
    }

    // rax <- rax (in, out); bump the refcount.
    void retain_str_rax() {
        E_.mov_r_r(RDI, RAX);
        emit_call(rt_label("sd_retain_str", 0));
    }

    // [rbp+off] <- sd_str*; release it.
    void release_str_from(int off) {
        E_.mov_r_mem(RDI, RBP, off);
        emit_call(rt_label("sd_release_str", 0));
    }

    // ── expression compilation ────────────────────────────────────────────────
    Vm type_vm(TypeKind k) {
        switch (k) {
            case TypeKind::Decimal: return Vm::Dec;
            case TypeKind::Text:    return Vm::Txt;
            default:                return Vm::Word;
        }
    }

    Vm compile_expr(Expression* e) {
        if (auto* num = dynamic_cast<NumberLiteral*>(e)) {
            E_.mov_r_imm(RAX, static_cast<int64_t>(num->value));
            return Vm::Word;
        }
        if (auto* dec = dynamic_cast<DecimalLiteral*>(e)) {
            E_.movsd_rip_xmm(XMM0, pool_double(dec->value));
            return Vm::Dec;
        }
        if (auto* s = dynamic_cast<StringLiteral*>(e)) {
            E_.lea_rip(RDI, pool_str(s->value));
            E_.mov_r_imm(RSI, static_cast<int64_t>(s->value.size()));
            emit_call(rt_label("sd_make_str", e->source_line()));
            return Vm::Txt;
        }
        if (auto* ch = dynamic_cast<CharLiteral*>(e)) {
            E_.mov_r_imm(RAX, static_cast<int64_t>(static_cast<int>(ch->value)));
            return Vm::Word;
        }
        if (auto* b = dynamic_cast<BoolLiteral*>(e)) {
            E_.mov_r_imm(RAX, b->value ? 1 : 0);
            return Vm::Word;
        }
        if (auto* id = dynamic_cast<Identifier*>(e)) {
            if (id->is_function_reference)
                err(e->source_line(), "elf backend v1: function values are not supported");
            auto it = ctx_->locals.find(id->name);
            if (it == ctx_->locals.end())
                err(e->source_line(), "elf backend v1: name '" + id->name + "' is not accessible here");
            int off = it->second;
            Vm vm = type_vm(e->resolved_type);
            if (vm == Vm::Txt) {
                E_.mov_r_mem(RAX, RBP, off);
                retain_str_rax();
                return Vm::Txt;
            }
            if (vm == Vm::Dec) {
                E_.movsd_xmm_mem(XMM0, RBP, off);
                return Vm::Dec;
            }
            E_.mov_r_mem(RAX, RBP, off);
            return Vm::Word;
        }
        if (auto* bin = dynamic_cast<BinaryExpr*>(e)) return compile_binary(bin);
        if (auto* n = dynamic_cast<NotExpr*>(e)) {
            if (type_vm(n->operand->resolved_type) != Vm::Word)
                err(e->source_line(), "elf backend v1: 'not' requires a word operand");
            compile_expr(n->operand.get());
            E_.alu_ri(ALU_CMP, RAX, 0);
            E_.setcc_al(CC_E);
            E_.movzx_q_b(RAX, RAX);
            return Vm::Word;
        }
        if (auto* n = dynamic_cast<NegExpr*>(e)) {
            if (type_vm(n->operand->resolved_type) == Vm::Dec) {
                compile_expr(n->operand.get());
                // xmm0 ^= -0.0 — exact sign flip, so -0.0 stays -0.0.
                E_.movsd_rip_xmm(XMM1, neg_mask());
                E_.xorpd_rr(XMM0, XMM1);
                return Vm::Dec;
            }
            compile_expr(n->operand.get());
            E_.neg_r(RAX);
            return Vm::Word;
        }
        if (auto* c = dynamic_cast<ConditionalExpr*>(e)) {
            compile_expr(c->condition.get());
            require_word_condition(c->condition.get(), "c?b condition");
            int else_l = new_label();
            int end_l = new_label();
            E_.test_rr(RAX, RAX);
            E_.jcc(CC_E, else_l);
            Vm then_vm = compile_expr(c->then_expr.get());
            E_.jmp(end_l);
            bind(else_l);
            Vm else_vm = compile_expr(c->else_expr.get());
            if (then_vm != else_vm)
                err(c->source_line(), "elf backend v1: conditional branches evaluate to different value kinds");
            bind(end_l);
            return then_vm;
        }
        if (auto* cst = dynamic_cast<CastExpr*>(e)) {
            Vm src = compile_expr(cst->operand.get());
            if (src == Vm::Word && (cst->target_type == TypeKind::Char || cst->target_type == TypeKind::Int)) {
                if (cst->target_type == TypeKind::Char && cst->operand->resolved_type != TypeKind::Char)
                    E_.movsx_q_b(RAX, RAX);   // int -> char: truncate + sign-extend
                return Vm::Word;
            }
            err(e->source_line(), "elf backend v1: unsupported cast target");
        }
        if (auto* idx = dynamic_cast<ArrayIndexExpr*>(e)) return compile_text_index(idx);
        if (auto* call = dynamic_cast<CallExpr*>(e)) return compile_call(call);
        err(e->source_line(), "elf backend v1: unsupported expression (build with the C backend)");
    }

    int neg_mask() { return pool_double(-0.0); }

    // s[i] -> char: retain the source, bounds-check through the runtime,
    // sign-extend the payload byte (C char semantics).
    Vm compile_text_index(ArrayIndexExpr* idx) {
        if (!idx->is_text || idx->base)
            err(idx->source_line(), "elf backend v1: array indexing is not supported (text[name] single index only)");
        int slot = slot_of(idx->name, idx->source_line());
        int h0 = ctx_->text_home[0], h1 = ctx_->text_home[1], h2 = ctx_->text_home[2];
        E_.mov_r_mem(RAX, RBP, slot);
        retain_str_rax();
        E_.mov_mem_r(RBP, h0, RAX);
        compile_expr(idx->index.get());
        E_.push_r(RAX);
        ctx_->pending++;
        E_.mov_r_mem(RAX, RBP, h0);
        E_.mov_r_mem(RDI, RAX, 16);      // len
        E_.pop_r(RSI);
        ctx_->pending--;
        emit_call(rt_label("sd_check_index", idx->source_line()));
        E_.mov_mem_r(RBP, h1, RAX);      // checked index
        E_.mov_r_mem(RAX, RBP, h0);
        E_.mov_r_mem(RAX, RAX, 24);      // data
        E_.mov_mem_r(RBP, h2, RAX);
        release_str_from(h0);
        E_.mov_r_mem(RAX, RBP, h1);
        E_.mov_r_mem(RDX, RBP, h2);
        E_.movsx_q_memidx(RAX, RDX, RAX);   // movsbq (rdx)[rax]
        return Vm::Word;
    }

    Vm compile_binary(BinaryExpr* e) {
        TypeKind lt = e->left->resolved_type;
        TypeKind rt = e->right->resolved_type;
        if (lt == TypeKind::Text && rt == TypeKind::Text) return compile_text_binary(e);
        if (lt == TypeKind::Decimal && rt == TypeKind::Decimal) return compile_dec_binary(e);
        if (!is_word(lt) || !is_word(rt))
            err(e->source_line(), "elf backend v1: unsupported operand types for '" + e->op + "'");

        const std::string& op = e->op;
        if (op == "&&" || op == "||") {
            int skip_l = new_label();
            int end_l = new_label();
            compile_expr(e->left.get());
            E_.test_rr(RAX, RAX);
            E_.jcc(op == "&&" ? CC_E : CC_NE, skip_l);
            compile_expr(e->right.get());
            // canonicalize the right result to 0/1 and fall through
            E_.test_rr(RAX, RAX);
            E_.setcc_al(CC_NE);
            E_.movzx_q_b(RAX, RAX);
            E_.jmp(end_l);
            bind(skip_l);
            E_.mov_r_imm(RAX, op == "&&" ? 0 : 1);
            bind(end_l);
            return Vm::Word;
        }

        compile_expr(e->left.get());
        E_.push_r(RAX);
        ctx_->pending++;
        compile_expr(e->right.get());
        E_.mov_r_r(RCX, RAX);            // right operand
        E_.pop_r(RAX);
        ctx_->pending--;                 // left operand

        if (op == "+")  { E_.alu_rr(ALU_ADD, RAX, RCX); return Vm::Word; }
        if (op == "-")  { E_.alu_rr(ALU_SUB, RAX, RCX); return Vm::Word; }
        if (op == "*")  { E_.imul_rr(RAX, RCX); return Vm::Word; }
        if (op == "/" || op == "%") {
            E_.cqo();
            E_.idiv_r(RCX);
            if (op == "%") E_.mov_r_r(RAX, RDX);
            return Vm::Word;
        }
        int cc = op == "==" ? CC_E   : op == "!=" ? CC_NE : op == "<"  ? CC_L :
                 op == "<=" ? CC_LE  : op == ">"  ? CC_G  : op == ">=" ? CC_GE : -1;
        if (cc < 0)
            err(e->source_line(), "elf backend v1: unsupported operator '" + op + "'");
        E_.alu_rr(ALU_CMP, RAX, RCX);
        E_.setcc_al(cc);
        E_.movzx_q_b(RAX, RAX);
        return Vm::Word;
    }

    // Operands evaluate to owned pointers; freed after the runtime call.
    int htext0() { return ctx_->text_home[0]; }
    int htext1() { return ctx_->text_home[1]; }
    int htext2() { return ctx_->text_home[2]; }

    Vm compile_text_binary(BinaryExpr* e) {
        int h0 = htext0(), h1 = htext1(), h2 = htext2();
        compile_expr(e->left.get());
        E_.push_r(RAX);
        ctx_->pending++;
        compile_expr(e->right.get());
        E_.mov_mem_r(RBP, h1, RAX);      // right
        E_.pop_r(RAX);
        ctx_->pending--;
        E_.mov_mem_r(RBP, h0, RAX);      // left
        if (e->op == "+") {
            // sd_concat(a, b) in HMX order: a = left, b = right
            E_.mov_r_mem(RDI, RBP, h0);
            E_.mov_r_mem(RSI, RBP, h1);
            emit_call(rt_label("sd_concat", e->source_line()));
            E_.mov_mem_r(RBP, h2, RAX);
            release_str_from(h0);
            release_str_from(h1);
            E_.mov_r_mem(RAX, RBP, h2);
            return Vm::Txt;
        }
        if (e->op == "==" || e->op == "!=" || e->op == "<" || e->op == "<=" ||
            e->op == ">" || e->op == ">=") {
            bool eq = e->op == "==" || e->op == "!=";
            E_.mov_r_mem(RDI, RBP, h0);
            E_.mov_r_mem(RSI, RBP, h1);
            emit_call(rt_label(eq ? "sd_str_equals" : "sd_str_cmp", e->source_line()));
            E_.mov_mem_r(RBP, h2, RAX);
            release_str_from(h0);
            release_str_from(h1);
            E_.mov_r_mem(RAX, RBP, h2);
            if (eq) {
                if (e->op == "!=") {
                    // equality result is canonical 0/1: invert for !=.
                    E_.alu_ri(ALU_CMP, RAX, 0);
                    E_.setcc_al(CC_E);
                    E_.movzx_q_b(RAX, RAX);
                }
                return Vm::Word;
            }
            // sd_str_cmp: result <0/0/>0 — canonicalize to 0/1 via cmp-to-zero.
            int cc = e->op == "<" ? CC_L : e->op == "<=" ? CC_LE
                     : e->op == ">" ? CC_G : CC_GE;
            E_.alu_ri(ALU_CMP, RAX, 0);
            E_.setcc_al(cc);
            E_.movzx_q_b(RAX, RAX);
            return Vm::Word;
        }
        err(e->source_line(), "elf backend v1: unsupported text operator '" + e->op + "'");
    }

    // Both operands are decimal (the resolver rejects mixed int/decimal
    // arithmetic). Mirror of the asm path: left parked in dec_scratch, right
    // starts in xmm0; the binop lands in xmm1 and is moved to xmm0.
    Vm compile_dec_binary(BinaryExpr* e) {
        const std::string& op = e->op;
        if (op == "==" || op == "!=" || op == "<" || op == "<=" ||
            op == ">" || op == ">=")
            return compile_dec_compare(e);
        if (op != "+" && op != "-" && op != "*" && op != "/")
            err(e->source_line(), "elf backend v1: decimal '" + op + "' is not supported");
        compile_expr(e->left.get());
        E_.movsd_mem_xmm(RBP, ctx_->dec_scratch, XMM0);
        compile_expr(e->right.get());
        E_.movsd_xmm_mem(XMM1, RBP, ctx_->dec_scratch);
        if (op == "+")      E_.addsd_rr(XMM1, XMM0);
        else if (op == "-") E_.subsd_rr(XMM1, XMM0);
        else if (op == "*") E_.mulsd_rr(XMM1, XMM0);
        else                E_.divsd_rr(XMM1, XMM0);
        E_.movsd_xmm_xmm(XMM0, XMM1);
        return Vm::Dec;
    }

    // Decimal comparisons via UCOMISD. Unordered (NaN) behaviour must match
    // C: == yields false, != true, everything else false. The jp branch
    // encodes exactly that; the ordered path uses the raw flag conditions
    // (setb/setbe/seta/setae/sete/setne).
    Vm compile_dec_compare(BinaryExpr* e) {
        compile_expr(e->left.get());
        E_.movsd_mem_xmm(RBP, ctx_->dec_scratch, XMM0);
        compile_expr(e->right.get());
        E_.movsd_xmm_mem(XMM1, RBP, ctx_->dec_scratch);
        E_.ucomisd_rr(XMM1, XMM0);          // compare left (xmm1) vs right (xmm0)
        int un_l = new_label();
        int end_l = new_label();
        E_.jcc(CC_P, un_l);
        int cc = e->op == "==" ? CC_E  : e->op == "!=" ? CC_NE
                 : e->op == "<" ? CC_B  : e->op == "<=" ? CC_BE
                 : e->op == ">"  ? CC_A : CC_AE;
        E_.setcc_al(cc);
        E_.movzx_q_b(RAX, RAX);
        E_.jmp(end_l);
        bind(un_l);
        E_.mov_r_imm(RAX, e->op == "!=" ? 1 : 0);   // unordered result
        bind(end_l);
        return Vm::Word;
    }

    // ── user function calls ──────────────────────────────────────────────────
    Vm compile_call(CallExpr* c) {
        if (c->is_struct_ctor)         err(c->source_line(), "elf backend v1: structs are not supported");
        if (c->is_partial)             err(c->source_line(), "elf backend v1: partial application is not supported");
        if (c->is_function_value_call) err(c->source_line(), "elf backend v1: function values are not supported");
        auto it = fns_by_name_.find(c->name);
        if (it == fns_by_name_.end()) {
            // Text/char builtins route through the runtime ABI.
            if (c->name == "length") {
                if (c->args.size() == 1 && c->args[0]->resolved_type == TypeKind::Text) {
                    compile_expr(c->args[0].get());            // owned sd_str*
                    E_.mov_mem_r(RBP, htext0(), RAX);
                    E_.mov_r_mem(RAX, RBP, htext0());
                    E_.mov_r_mem(RAX, RAX, 16);                // len
                    E_.mov_mem_r(RBP, htext1(), RAX);
                    release_str_from(htext0());
                    E_.mov_r_mem(RAX, RBP, htext1());
                    return Vm::Word;
                }
                err(c->source_line(), "elf backend v1: length() of arrays is not supported");
            }
            if (c->name == "substring") {
                compile_expr(c->args[0].get());                // owned sd_str*
                E_.push_r(RAX);
                E_.push_r(RAX);
                ctx_->pending += 2;                            // + duplicate for post-call release
                compile_expr(c->args[1].get());
                E_.push_r(RAX);
                ctx_->pending++;
                compile_expr(c->args[2].get());
                E_.push_r(RAX);
                ctx_->pending++;
                E_.pop_r(RCX);
                ctx_->pending--;      // end
                E_.pop_r(RSI);
                ctx_->pending--;      // start
                E_.pop_r(RDI);
                ctx_->pending--;      // sd_str* (duplicate)
                E_.mov_r_r(RDX, RCX);
                E_.alu_rr(ALU_SUB, RDX, RSI);                  // len = end - start
                emit_call(rt_label("sd_str_view", c->source_line()));
                E_.mov_mem_r(RBP, htext2(), RAX);
                E_.pop_r(RAX);
                ctx_->pending--;      // original copy
                E_.mov_r_r(RDI, RAX);
                emit_call(rt_label("sd_release_str", 0));
                E_.mov_r_mem(RAX, RBP, htext2());
                return Vm::Txt;
            }
            if (c->name == "ord") {
                if (c->args.size() == 1) {
                    compile_expr(c->args[0].get());
                    E_.movzx_q_b(RAX, RAX);
                    return Vm::Word;
                }
                err(c->source_line(), "elf backend v1: 'ord' takes exactly one argument");
            }
            if (c->name == "chr") {
                if (c->args.size() != 1)
                    err(c->source_line(), "elf backend v1: 'chr' takes exactly one argument");
                compile_expr(c->args[0].get());
                int panic_l = new_label();
                int done_l = new_label();
                E_.mov_r_r(RDX, RAX);
                E_.alu_ri(ALU_CMP, RAX, 0);
                E_.jcc(CC_L, panic_l);
                E_.alu_ri(ALU_CMP, RAX, 255);
                E_.jcc(CC_G, panic_l);
                E_.movzx_q_b(RAX, RAX);
                E_.jmp(done_l);
                bind(panic_l);
                E_.mov_r_r(RDI, RDX);
                emit_call(rt_label("_hmx_panic_chr", c->source_line()));
                bind(done_l);
                return Vm::Word;
            }
            err(c->source_line(), "elf backend v1: builtin '" + c->name + "' is not supported (build with the C backend)");
        }
        FunctionDecl* fn = it->second;
        size_t n = c->args.size();
        if (n != fn->params.size())
            err(c->source_line(), "elf backend v1: argument count mismatch for '" + fn->name + "'");
        if (n > 6)
            err(c->source_line(), "elf backend v1: too many call arguments (max 6)");

        // SysV plan: word args (including text pointers) fill CALL_REGS in
        // order; decimals fill xmm0.. in order. Every argument is spilled on
        // the stack exactly once; text arguments are additionally parked in
        // this call site's reserved slots so the caller can drop its +1
        // after the call (nested calls use their own regions, so parking
        // composes safely).
        std::vector<std::pair<Vm, int>> plan(n);
        int wi = 0, xi = 0;
        for (size_t i = 0; i < n; i++) {
            if (fn->params[i].type == TypeKind::Decimal) plan[i] = {Vm::Dec, xi++};
            else plan[i] = {Vm::Word, wi++};
        }
        for (size_t i = 0; i < n; i++) {
            compile_expr(c->args[i].get());
            if (plan[i].first == Vm::Dec) {
                E_.alu_ri(ALU_SUB, RSP, 8);
                E_.movsd_mem_xmm(RSP, 0, XMM0);
                ctx_->pending++;
            } else {
                E_.push_r(RAX);
                ctx_->pending++;
            }
        }
        for (size_t k = n; k-- > 0;) {
            if (plan[k].first == Vm::Dec) {
                E_.movsd_xmm_mem(plan[k].second, RSP, 0);
                E_.alu_ri(ALU_ADD, RSP, 8);
                ctx_->pending--;
            } else {
                E_.pop_r(RAX);
                ctx_->pending--;
                if (c->args[k]->resolved_type == TypeKind::Text) {
                    int ordinal = 0;
                    for (size_t j = 0; j < k; j++)
                        if (c->args[j]->resolved_type == TypeKind::Text) ordinal++;
                    const int base = call_text_slots_[c];
                    E_.mov_mem_r(RBP, base - 8 * ordinal, RAX);
                }
                E_.mov_r_r(CALL_REGS[plan[k].second], RAX);
            }
        }
        emit_call(fn_label(fn));
        // drop the caller's +1 on each text argument from its reserved slot;
        // the releases clobber rax/xmm0, so a call result is parked first.
        size_t can_text = 0;
        for (size_t i = 0; i < n; i++)
            if (c->args[i]->resolved_type == TypeKind::Text) can_text++;
        if (can_text > 0) {
            if (fn->has_return_type && fn->return_type == TypeKind::Decimal)
                E_.movsd_mem_xmm(RBP, ctx_->dec_scratch, XMM0);
            else
                E_.mov_mem_r(RBP, htext0(), RAX);
        }
        for (size_t i = 0, t = 0; i < n; i++) {
            if (c->args[i]->resolved_type != TypeKind::Text) continue;
            const int base = call_text_slots_[c];
            E_.mov_r_mem(RDI, RBP, base - 8 * t);
            t++;
            emit_call(rt_label("sd_release_str", 0));
        }
        if (can_text > 0) {
            if (fn->has_return_type && fn->return_type == TypeKind::Decimal)
                E_.movsd_xmm_mem(XMM0, RBP, ctx_->dec_scratch);
            else
                E_.mov_r_mem(RAX, RBP, htext0());
        }
        return !fn->has_return_type ? Vm::Word : type_vm(fn->return_type);
    }

    int fn_label(FunctionDecl* fn) {
        if (fn == main_fn_) return ctx_main_.label_id;
        auto* c = fn_ctx_[fn];
        return c->label_id;
    }

    // ── print (per-argument helper calls replace printf) ─────────────────────
    // Args are evaluated left-to-right and spilled on the stack; the write
    // phase walks them in argument order via rsp-relative loads (the stack
    // still holds every argument, so no per-arg frame parking is needed).
    // Byte stream: digits/char byte/decimal digits/text bytes with " "
    // separators and a "\n" terminator — identical to printf.
    void emit_print(PrintStmt* s) {
        size_t n = s->args.size();
        std::vector<Vm> modes(n);
        for (size_t i = 0; i < n; i++) {
            TypeKind t = s->args[i]->resolved_type;
            if (!is_v1_value(t))
                err(s->line, "elf backend v1: unsupported print argument type");
            modes[i] = type_vm(t);
        }

        // evaluate + spill each arg
        for (size_t i = 0; i < n; i++) {
            compile_expr(s->args[i].get());
            if (modes[i] == Vm::Dec) {
                E_.alu_ri(ALU_SUB, RSP, 8);
                E_.movsd_mem_xmm(RSP, 0, XMM0);
                ctx_->pending++;
            } else {
                E_.push_r(RAX);
                ctx_->pending++;
            }
        }
        // write the bytes in argument order
        for (size_t k = 0; k < n; k++) {
            if (k > 0) emit_wchr_imm(' ');
            long off = 8L * static_cast<long>(n - 1 - k);   // arg k sits here
            if (modes[k] == Vm::Dec) {
                E_.movsd_xmm_mem(XMM0, RSP, off);
                emit_call(rt_label("_hmx_w_f64", s->line));
            } else if (modes[k] == Vm::Txt) {
                E_.mov_r_mem(RAX, RSP, off);
                E_.mov_r_mem(RDI, RAX, 16);        // len
                E_.mov_r_mem(RSI, RAX, 24);        // data
                emit_call(rt_label("_hmx_w_text", s->line));
                E_.mov_r_mem(RDI, RSP, off);
                emit_call(rt_label("sd_release_str", 0));
            } else {
                bool as_char = s->args[k]->resolved_type == TypeKind::Char;
                E_.mov_r_mem(RAX, RSP, off);
                E_.mov_r_r(RDI, RAX);
                emit_call(rt_label(as_char ? "_hmx_w_char" : "_hmx_w_i64", s->line));
            }
        }
        E_.alu_ri(ALU_SUB, RSP, 8L * static_cast<long>(n));
        ctx_->pending -= static_cast<int>(n);
        emit_wchr_imm('\n');
    }

    // ── statements ───────────────────────────────────────────────────────────
    const int& slot_of(const std::string& name, int line) {
        auto it = ctx_->locals.find(name);
        if (it == ctx_->locals.end())
            err(line, "elf backend v1: name '" + name + "' is not assignable here");
        return it->second;
    }

    void require_word_condition(Expression* e, const char* where) {
        if (!is_word(e->resolved_type))
            err(e->source_line(), std::string("elf backend v1: ") + where + " must be a word value (int/bool/char)");
    }

    void store_dropdown(int off, Vm vm) {
        if (vm == Vm::Dec)
            E_.movsd_mem_xmm(RBP, off, XMM0);
        else
            E_.mov_mem_r(RBP, off, RAX);
    }
    void register_text_slot(int off) {
        auto& v = ctx_->text_release;
        if (std::find(v.begin(), v.end(), off) == v.end()) v.push_back(off);
    }

    void emit_node(Ctx& c, const ir::Node& n) {
        ctx_ = &c;
        switch (n.kind) {
            case ir::SKind::VarDecl: {
                auto* v = static_cast<VarDecl*>(n.ast);
                auto ds = decl_slots_.find(v);
                if (ds == decl_slots_.end())
                    err(v->line, "elf backend v1: internal: undeclared name '" + v->name + "'");
                const int off = ds->second;
                c.locals[v->name] = off;   // bind the name for this scope
                if (!v->initializer) {
                    if (decl_is_text(v))
                        err(v->line, "elf backend v1: uninitialized text local would dangle (text slots are released at function exit)");
                    E_.mov_r_imm(RAX, 0);
                    E_.mov_mem_r(RBP, off, RAX);
                    return;
                }
                Vm vm = compile_expr(v->initializer.get());
                if (vm == Vm::Txt) {
                    // owned new ref; the slot may already hold a value from a
                    // previous execution of this declaration inside a loop
                    E_.push_r(RAX);
                    ctx_->pending++;
                    release_str_from(off);
                    E_.pop_r(RAX);
                    ctx_->pending--;
                    E_.mov_mem_r(RBP, off, RAX);
                    register_text_slot(off);
                } else store_dropdown(off, vm);
                return;
            }
            case ir::SKind::Assign: {
                auto* s = static_cast<AssignStmt*>(n.ast);
                const int& off = slot_of(s->name, s->line);
                TypeKind rhs_t = s->rhs ? s->rhs->resolved_type : TypeKind::Int;
                if (s->op == "=") {
                    Vm vm = compile_expr(s->rhs.get());
                    if (vm == Vm::Txt) {
                        // new ref is owned; release the old value AFTER
                        E_.push_r(RAX);
                        ctx_->pending++;
                        release_str_from(off);
                        E_.pop_r(RAX);
                        ctx_->pending--;
                        E_.mov_mem_r(RBP, off, RAX);
                        register_text_slot(off);
                    } else store_dropdown(off, vm);
                    return;
                }
                if (s->op == "++" || s->op == "--") {
                    if (rhs_t == TypeKind::Decimal)
                        err(s->line, "elf backend v1: '++'/'--' on a decimal is not supported");
                    E_.alu_mi(s->op == "++" ? ALU_ADD : ALU_SUB, RBP, off, 1);
                    return;
                }
                if (rhs_t == TypeKind::Decimal || rhs_t == TypeKind::Text)
                    err(s->line, "elf backend v1: compound assignment on decimals/text is not supported");
                compile_expr(s->rhs.get());
                E_.mov_r_r(RCX, RAX);
                E_.mov_r_mem(RAX, RBP, off);
                const std::string& op = s->op;
                if (op == "+=") E_.alu_rr(ALU_ADD, RAX, RCX);
                else if (op == "-=") E_.alu_rr(ALU_SUB, RAX, RCX);
                else if (op == "*=") E_.imul_rr(RAX, RCX);
                else if (op == "/=" || op == "%=") {
                    E_.cqo();
                    E_.idiv_r(RCX);
                    if (op == "%=") E_.mov_r_r(RAX, RDX);
                } else err(s->line, "elf backend v1: unsupported assignment operator '" + op + "'");
                E_.mov_mem_r(RBP, off, RAX);
                return;
            }
            case ir::SKind::ExprStmt: {
                auto* s = static_cast<ExprStmt*>(n.ast);
                Vm vm = compile_expr(s->expr.get());
                if (vm == Vm::Txt) {
                    E_.mov_r_r(RDI, RAX);
                    emit_call(rt_label("sd_release_str", 0));
                }
                return;
            }
            case ir::SKind::Print:
                emit_print(static_cast<PrintStmt*>(n.ast));
                return;
            case ir::SKind::If: {
                auto* s = static_cast<IfStmt*>(n.ast);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "if condition");
                int else_l = new_label();
                int end_l = new_label();
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, s->has_else ? else_l : end_l);
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                if (s->has_else) {
                    E_.jmp(end_l);
                    bind(else_l);
                    emit_scope(c, [&] {
                        for (auto& b : n.else_body) emit_node(c, *b);
                    });
                }
                bind(end_l);
                return;
            }
            case ir::SKind::While: {
                auto* s = static_cast<WhileStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                bind(top_l);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "while condition");
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, end_l);
                c.loops.push_back({end_l, top_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                E_.jmp(top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::DoWhile: {
                auto* s = static_cast<DoWhileStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                int cont_l = new_label();
                bind(top_l);
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "do-while condition");
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_NE, top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::For: {
                auto* s = static_cast<ForStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                // the header declaration is scoped to header + body
                std::string hdr;
                bool had = false;
                int prev = 0;
                if (n.init && n.init->kind == ir::SKind::VarDecl) {
                    hdr = static_cast<VarDecl*>(n.init->ast)->name;
                    auto it = c.locals.find(hdr);
                    if (it != c.locals.end()) { had = true; prev = it->second; }
                }
                if (n.init) emit_node(c, *n.init);
                bind(top_l);
                if (s->condition) {
                    compile_expr(s->condition.get());
                    require_word_condition(s->condition.get(), "for condition");
                } else {
                    E_.mov_r_imm(RAX, 1);
                }
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, end_l);
                int cont_l = new_label();
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                if (n.update) emit_node(c, *n.update);
                E_.jmp(top_l);
                bind(end_l);
                if (had) c.locals[hdr] = prev;
                else if (!hdr.empty()) c.locals.erase(hdr);
                return;
            }
            case ir::SKind::Loop: {
                auto* s = static_cast<LoopStmt*>(n.ast);
                require_word_condition(s->count.get(), "loop count");
                auto slots = loop_slots_[s];
                int top_l = new_label();
                int end_l = new_label();
                compile_expr(s->count.get());
                E_.mov_mem_r(RBP, slots.first, RAX);
                E_.mov_r_imm(RAX, 0);
                E_.mov_mem_r(RBP, slots.second, RAX);
                bind(top_l);
                E_.mov_r_mem(RAX, RBP, slots.second);
                E_.alu_rm(ALU_CMP, RAX, RBP, slots.first);
                E_.jcc(CC_GE, end_l);
                int cont_l = new_label();
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                E_.alu_mi(ALU_ADD, RBP, slots.second, 1);
                E_.jmp(top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::Break:
                if (c.loops.empty()) err(n.ast->line, "elf backend v1: break outside a loop");
                E_.jmp(c.loops.back().brk);
                return;
            case ir::SKind::Continue:
                if (c.loops.empty()) err(n.ast->line, "elf backend v1: continue outside a loop");
                E_.jmp(c.loops.back().cont);
                return;
            case ir::SKind::Return: {
                auto* s = static_cast<ReturnStmt*>(n.ast);
                if (!s->values.empty()) {
                    if (s->values.size() > 1)
                        err(s->line, "elf backend v1: multi-value return is a tuple (not supported)");
                    Vm vm = compile_expr(s->values[0].get());
                    if (c.is_main_body) {
                        if (vm != Vm::Word)
                            err(s->line, "elf backend v1: main must return an int");
                        E_.mov_mem_r(RBP, c.ret_slot, RAX);
                    } else {
                        // Park the return value: the epilogue's text releases
                        // clobber rax/xmm0, so the tail reloads it.
                        if (vm == Vm::Dec)
                            E_.movsd_mem_xmm(RBP, c.ret_slot, XMM0);
                        else
                            E_.mov_mem_r(RBP, c.ret_slot, RAX);
                    }
                }
                E_.jmp(c.ret_label);
                return;
            }
            case ir::SKind::Defer:
                err(n.ast->line, "elf backend v1: defer is not supported");
                return;
            case ir::SKind::Try:
                err(n.ast->line, "elf backend v1: try/catch is not supported");
                return;
            case ir::SKind::Switch:
                err(n.ast->line, "elf backend v1: switch is not supported");
                return;
            case ir::SKind::Foreach:
                err(n.ast->line, "elf backend v1: foreach is not supported");
                return;
            case ir::SKind::MultiAssign:
            case ir::SKind::DestructDecl:
            case ir::SKind::ArrayAssign:
            case ir::SKind::ElementAssign:
            case ir::SKind::MemberAssign:
                err(n.ast->line, "elf backend v1: array/tuple/struct assignment is not supported");
                return;
            case ir::SKind::TypeDecl:
                err(n.ast->line, "elf backend v1: type declarations are not supported");
                return;
            case ir::SKind::FuncDecl:
                return;  // registered up front
        }
        return;   // reachable only if new ir node kinds appear; make it an emit-side error
    }

private:
    // Emit-side mirror of scan_scope: unbind names the block declared so a
    // later sibling block rebinds cleanly through its own declaration.
    template <typename F>
    void emit_scope(Ctx& c, F&& f) {
        std::map<std::string, int> before(c.locals);
        f();
        for (auto it = c.locals.begin(); it != c.locals.end();) {
            if (before.count(it->first) == 0) it = c.locals.erase(it);
            else ++it;
        }
    }

    void check_fn_signature(FunctionDecl* fn) {
        for (auto& p : fn->params) {
            if (!is_v1_value(p.type))
                err(fn->line, "elf backend v1: parameter type of '" + fn->name + "' is unsupported (word/decimal/text only)");
        }
        if (fn->has_return_type && !is_v1_value(fn->return_type))
            err(fn->line, "elf backend v1: return type of '" + fn->name + "' is unsupported");
    }

    void emit_function(FunctionDecl* fn) {
        Ctx& c = *fn_ctx_[fn];
        bind(c.label_id);
        emit_frame_head(c);
        // park register args into their slots (SysV: words in CALL_REGS,
        // decimals in xmm0.. in order of appearance)
        int xi = 0;
        for (size_t i = 0; i < fn->params.size(); i++) {
            int off = c.locals[fn->params[i].name];
            if (fn->params[i].type == TypeKind::Decimal)
                E_.movsd_mem_xmm(RBP, off, XMM0 + xi++);
            else
                E_.mov_mem_r(RBP, off, CALL_REGS[i]);
        }

        auto body_ir = ir::build(fn->body);
        for (auto& n : body_ir) emit_node(c, *n);
        emit_frame_tail(c);
    }
};

}  // namespace (internal)

std::vector<uint8_t> emit_elf(Program& program, const std::string& source_file) {
    ElfBackend backend(program, source_file);
    return backend.run();
}

}  // namespace backend
